public class Bingo {
    int [][] granniesCard = new int[5][5];
    int grannyWins = 0;

    public static void main(String[] args) throws Throwable {
        new Bingo().run();
    }

    public void run() throws Throwable {
        Scanner kb = new Scanner(new File("bingo.dat"));

        for(int x = 0; x < 5; x++) {
            for(int y = 0; y < 5; y++) {
                granniesCard[x][y] = kb.nextInt();
            }
        }

        int times = kb.nextInt();

        while(times-->0) {
            int cards = kb.nextInt(); long seed = kb.nextLong();
            Random r = new Random(seed);
            grannyWins = 0;

            ArrayList<int[][]> bingoCards = new ArrayList<>();
            for(int x = 0; x < cards; x++) {
                int [][] card = new int[5][5];
                for(int i = 0; i < 5; i++) {
                    for (int j = 0; j < 5; j++) {
                        card[i][j] = kb.nextInt();
                    }
                }
                bingoCards.add(card);
            }
            bingoCards.addFirst(granniesCard);

            for(int x = 0; x < 1000; x++) {
                ArrayList<int[][]> gameCards = new ArrayList<>();
                for(int[][] card : bingoCards) {
                    int[][] copy = new int[5][5];
                    for(int i = 0; i < 5; i++)
                        copy[i] = card[i].clone();
                    gameCards.add(copy);
                }
                simulateGame(gameCards, r);
            }

            System.out.printf("%.1f%% Win Rate.%n", grannyWins / 10.0);
        }
    }
    private void simulateGame(ArrayList<int[][]> cards, Random r) {
        boolean done = false;

        while(!done) {
            int number = r.nextInt(1, 76);
            for(int [][] arr : cards) {
                for(int i = 0; i < 5; i++) {
                    for(int j = 0; j < 5; j++) {
                        if (arr[i][j] == number) {
                            arr[i][j] = 0;
                        }
                    }
                }
            }
            done = checkWin(cards);
        }
    }
    private boolean checkWin(ArrayList<int[][]> cards) {
        for(int x = 0; x < cards.size(); x++) {
            int [][] card = cards.get(x);
            // check rows
            for(int i = 0; i< 5; i++) {
                boolean win = true;
                for(int j = 0; j < 5; j++) {
                    if (card[i][j] != 0) {
                        win = false;
                        break;
                    }
                }
                if (win) {
                    if (x == 0)
                        grannyWins++;
                    return true;
                }
            }
            // check columns
            for(int j = 0; j< 5; j++) {
                boolean win = true;
                for(int i = 0; i < 5; i++) {
                    if (card[i][j] != 0) {
                        win = false;
                        break;
                    }
                }
                if (win) {
                    if (x == 0)
                        grannyWins++;
                    return true;
                }
            }
            if (card[0][0] == card[1][1] && card[1][1] == card[2][2] && card[2][2] == card[3][3] && card[3][3] == card[4][4]) {
                if(x == 0)
                    grannyWins++;
                return true;
            }
            if (card[0][4] == card[1][3] && card[1][3] == card[2][2] && card[2][2] == card[3][1] && card[3][1] == card[4][0]) {
                if(x == 0)
                    grannyWins++;
                return true;
            }
        }
        return false;
    }
}

import java.io.File;
import java.io.FileNotFoundException;
import java.util.*;

public class Bango {

    static final Map<String, Integer> TIER_SCORE = new HashMap<>();
    static {
        TIER_SCORE.put("Bronze",   1);
        TIER_SCORE.put("Silver",   2);
        TIER_SCORE.put("Gold",     3);
        TIER_SCORE.put("Platinum", 4);
        TIER_SCORE.put("Diamond",  5);
    }

    static class Player {
        // Raw fields
        String username;
        String tier;
        int wins, losses, kills, deaths, assists, headshots;

        // Computed metrics
        int    tierScore;
        double winRate;
        double combatScore;
        double headshotPct;

        Player(String username, String tier,
               int wins, int losses,
               int kills, int deaths,
               int assists, int headshots) {
            this.username  = username;
            this.tier      = tier;
            this.wins      = wins;
            this.losses    = losses;
            this.kills     = kills;
            this.deaths    = deaths;
            this.assists   = assists;
            this.headshots = headshots;

            this.tierScore    = TIER_SCORE.get(tier);
            this.winRate      = (double) wins / (wins + losses);
            this.combatScore  = (kills * 1.0 + assists * 0.5) / Math.max(deaths, 1);
            this.headshotPct  = (double) headshots / Math.max(kills, 1) * 100.0;
        }
    }

    // Comparator: higher tier > higher winRate > higher combatScore > higher HS% > username A-Z
    static final Comparator<Player> RANKING = Comparator
            .comparingInt((Player p) -> -p.tierScore)
            .thenComparingDouble((Player p) -> -p.winRate)
            .thenComparingDouble((Player p) -> -p.combatScore)
            .thenComparingDouble((Player p) -> -p.headshotPct)
            .thenComparing(p -> p.username);

    static final String SEPARATOR = "------------------------------------------------------------------------";

    // Column widths (not counting separators)
    // RANK=6, USERNAME=22, TIER=10, WIN%=8, COMBAT=8, HS%=7
    static String formatRow(String rank, String username, String tier,
                            String winPct, String combat, String hsPct) {
        return String.format("%-6s | %-22s | %-10s | %-8s | %-8s | %-7s",
                rank, username, tier, winPct, combat, hsPct);
    }

    public static void main(String[] args) throws FileNotFoundException {
        Scanner sc = new Scanner(new File("bango.dat"));

        int n = Integer.parseInt(sc.nextLine().trim());
        List<Player> players = new ArrayList<>();

        for (int i = 0; i < n; i++) {
            String[] parts = sc.nextLine().trim().split("\\s+");
            String username  = parts[0];
            String tier      = parts[1];
            int wins         = Integer.parseInt(parts[2]);
            int losses       = Integer.parseInt(parts[3]);
            int kills        = Integer.parseInt(parts[4]);
            int deaths       = Integer.parseInt(parts[5]);
            int assists      = Integer.parseInt(parts[6]);
            int headshots    = Integer.parseInt(parts[7]);
            players.add(new Player(username, tier, wins, losses, kills, deaths, assists, headshots));
        }

        players.sort(RANKING);

        // Print table
        System.out.println(SEPARATOR);
        System.out.println(formatRow("PLACE", "USERNAME", "RANK", "WIN%", "COMBAT", "HS%"));
        System.out.println(SEPARATOR);

        for (int i = 0; i < players.size(); i++) {
            Player p = players.get(i);
            String rank    = "#" + (i + 1);
            String tier    = "[" + p.tier + "]";
            String winPct  = String.format("%.2f", p.winRate * 100);
            String combat  = String.format("%.2f", p.combatScore);
            String hsPct   = String.format("%.2f", p.headshotPct);
            System.out.println(formatRow(rank, p.username, tier, winPct, combat, hsPct));
        }

        System.out.println(SEPARATOR);
        sc.close();
    }
}

import java.io.File;
import java.util.*;

public class Bongo {
    static Map<String, Integer> spamWordCounts = new HashMap<>();
    static Map<String, Integer> hamWordCounts = new HashMap<>();
    static Set<String> vocabulary = new HashSet<>();

    static int spamEmails = 0;
    static int hamEmails = 0;

    static int spamTotalWords = 0;
    static int hamTotalWords = 0;

    public static void main(String[] args) throws Throwable {
        new Bongo().run();
    }

    public void run() throws Throwable {
        Scanner sc = new Scanner(new File("bongo.dat"));

        int N = sc.nextInt();
        int M = sc.nextInt();
        sc.nextLine();

        // Read training emails
        for (int i = 0; i < N; i++) {
            String line = sc.nextLine();
            String[] parts = line.split(" ", 2);

            String label = parts[0];
            String[] words = parts[1].split(" ");

            if (label.equals("spam")) {
                spamEmails++;
                for (String word : words) {
                    vocabulary.add(word);
                    spamWordCounts.put(word, spamWordCounts.getOrDefault(word, 0) + 1);
                    spamTotalWords++;
                }
            } else {
                hamEmails++;
                for (String word : words) {
                    vocabulary.add(word);
                    hamWordCounts.put(word, hamWordCounts.getOrDefault(word, 0) + 1);
                    hamTotalWords++;
                }
            }
        }

        // Classify test emails
        for (int i = 0; i < M; i++) {
            String email = sc.nextLine();
            String result = classify(email);
            System.out.println(result);
        }

        sc.close();
    }
    static String classify(String email) {
        String[] words = email.split(" ");

        int totalEmails = spamEmails + hamEmails;

        double logSpam = Math.log((double) spamEmails / totalEmails);
        double logHam = Math.log((double) hamEmails / totalEmails);

        int vocabSize = vocabulary.size();

        for (String word : words) {

            int spamCount = spamWordCounts.getOrDefault(word, 0);
            int hamCount = hamWordCounts.getOrDefault(word, 0);

            double spamProb = (double) (spamCount + 1) / (spamTotalWords + vocabSize);
            double hamProb = (double) (hamCount + 1) / (hamTotalWords + vocabSize);

            logSpam += Math.log(spamProb);
            logHam += Math.log(hamProb);
        }

        if (logSpam > logHam) {
            return "spam";
        } else {
            return "ham";
        }
    }
}

